import{_ as e,c as t,o,ag as i}from"./chunks/framework.Bzez9NG9.js";const a="/space/img/connections_table_list.png",s="/space/img/found_connections.png",c="/space/img/new_connection.png",f=JSON.parse('{"title":"Connections","description":"Configure and test IBM Planning Analytics connections, including authentication, job credentials, and connection access.","frontmatter":{"title":"Connections","description":"Configure and test IBM Planning Analytics connections, including authentication, job credentials, and connection access.","keywords":["TM1 REST API","CAM","SSO","service account"],"outline":"deep"},"headers":[],"relativePath":"doc/configuration/connections.md","filePath":"doc/configuration/connections.md"}'),r={name:"doc/configuration/connections.md"};function l(d,n,g,u,h,p){return o(),t("div",null,n[0]||(n[0]=[i('<h1 id="connections" tabindex="-1">Connections <a class="header-anchor" href="#connections" aria-label="Permalink to &quot;Connections&quot;">​</a></h1><p>Connections define how SPACE talks to each IBM Planning Analytics server.</p><p><img src="'+a+'" alt="Connections list" data-zoomable=""></p><p>The table displays the name and REST API URL of every registered server. Use <strong>Detect</strong> to discover PA servers that SPACE can reach, or select rows to edit/delete existing connections.</p><h2 id="detecting-servers" tabindex="-1">Detecting servers <a class="header-anchor" href="#detecting-servers" aria-label="Permalink to &quot;Detecting servers&quot;">​</a></h2><p>Click <strong>Detect</strong> to scan the current environment for TM1 endpoints. Select any results to add them automatically.</p><p><img src="'+s+'" alt="Found connections modal" data-zoomable=""></p><h2 id="creating-or-editing-a-connection" tabindex="-1">Creating or editing a connection <a class="header-anchor" href="#creating-or-editing-a-connection" aria-label="Permalink to &quot;Creating or editing a connection&quot;">​</a></h2><p>Choose <strong>New connection</strong> (or open an existing one) to configure the server details.</p><p><img src="'+c+'" alt="New connection modal" data-zoomable=""></p><p>Provide:</p><ul><li><strong>Connection name</strong> – friendly label used throughout SPACE.</li><li><strong>Connection URL</strong> – TM1 REST API endpoint (e.g., <code>https://servername:8014/api/v1/</code>).</li><li><strong>Authentication</strong> – pick the method that matches your deployment: <ul><li>IBM Planning Analytics Cloud (SSO)</li><li>IBM Planning Analytics Cloud (Non-Interactive)</li><li>IBM Planning Analytics Local (SSO)</li><li>IBM Planning Analytics Local (CAM)</li><li>IBM Planning Analytics Local (Basic)</li></ul></li><li><strong>Client ID / Secret / Proxy URL</strong> – fields vary based on the authentication method.</li></ul><p>Use the built-in <strong>Test connection</strong> button to validate credentials before saving. After a connection is active you can optionally add <strong>Job credentials</strong> (service account used by schedules) and limit <strong>Connection access</strong> to specific roles so only approved users can trigger jobs or queries against that server.</p><h2 id="related-guides" tabindex="-1">Related guides <a class="header-anchor" href="#related-guides" aria-label="Permalink to &quot;Related guides&quot;">​</a></h2><ul><li><a href="./access.html">Access</a> explains SPACE users, roles, and tokens.</li><li><a href="./jobs.html">Jobs</a> explains scheduled tasks that use connection credentials.</li><li><a href="./#my-environments">My environments</a> maps personal PAW URLs to a SPACE host; TM1 server connections are configured here.</li></ul>',15)]))}const _=e(r,[["render",l]]);export{f as __pageData,_ as default};
